examples.JavaScript:
// Execute no backend. Configure ambiente e credencial.
const base = process.env.CATALISA_BASE_URL;
const token = process.env.CATALISA_TOKEN;
const path = '/decision-engine/api/v1/decisions/{decisionId}/execute';

const response = await fetch(base + path, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${token}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    "input": {
      "age": 25
    }
  })
});

if (!response.ok) {
  throw new Error(`HTTP ${response.status}`);
}
const result = await response.json();

